        "“As for Me, behold, My covenant is with you, and you will be a father of many nations.”",
        "“Neither will your name any more be called Abram, but your name will be Abraham; for I have made you a father of many nations.”",
        "“And I will make you exceedingly fruitful, and I will make nations of you, and kings will come out of you.”",
        "“And I will establish My covenant between Me and you and your descendants after you in their generations for an everlasting covenant, to be a God to you, and to your descendants after you.”",
        "“And I will give to you, and to your descendants after you, the land where you are a stranger, all the land of Canaan, for an everlasting possession; and I will be their God.”",
        "And God said to Abraham, “You will keep My covenant therefore, you, and your descendants after you in their generations.”",
        "“This is My covenant, which you will keep, between Me and you and your descendants after you; Every male child among you will be circumcised.”",
        "“And you will circumcise the flesh of your foreskin; and it will be a sign of the covenant between Me and you.”",
        "“And he that is eight days old will be circumcised among you, every male child in your generations, he that is born in the house, or bought with money of any stranger, which is not of your descendants.”",
        "“He that is born in your house, and he that is bought with your money, must be circumcised: and My covenant will be in your flesh for an everlasting covenant.”",
        "“And the uncircumcised male child whose flesh of his foreskin is not circumcised, that soul will be cut off from his people; he has broken My covenant.”",
        "And God said to Abraham, “As for Sarai your wife, you will not call her name Sarai, but Sarah will her name be.”",
        "“And I will bless her, and give you a son also of her: yes, I will bless her, and she will be a mother of nations; kings of people will be of her.”",
        "Then Abraham fell upon his face, and laughed, and said in his heart, “Will a child be born to him that is a hundred years old? And will Sarah, that is ninety years old, bear?”",
        "And Abraham said to God, “Oh that Ishmael might live before You!”",
        "And God said, “Sarah your wife will bear you a son indeed; and you will call his name Isaac: and I will establish My covenant with him for an everlasting covenant, and with his descendants after him.”",
        "“And as for Ishmael, I have heard you: Behold, I have blessed him, and will make him fruitful, and will multiply him exceedingly; twelve princes will he father, and I will make him a great nation.”",
        "“But My covenant will I establish with Isaac, which Sarah will bear to you at this set time in the next year.”",
