        "And the Lord said, “I have surely seen the affliction of My people who are in Egypt, and have heard their cry by reason of their taskmasters, for I know their sorrows.”",
        "“And I am come down to deliver them out of the hand of the Egyptians, and to bring them up out of that land to a good land and a large, to a land flowing with milk and honey, to the place of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites.”",
        "“Now therefore, behold, the cry of the children of Israel has come to Me. And I have also seen the oppression with which the Egyptians oppress them.”",
        "“Come now therefore, and I will send you to Pharaoh, that you may bring forth My people the children of Israel out of Egypt.”",
        "And Moses said to God, “Who am I, that I should go to Pharaoh, and that I should bring forth the children of Israel out of Egypt?”",
        "And He said, “Certainly I will be with you, and this will be a token to you, that I have sent you: When you have brought forth the people out of Egypt, you will serve God on this mountain.”",
        "And Moses said to God, “Behold, when I come to the children of Israel, and will say to them, ‘The God of your fathers has sent me to you’, and they will say to me, ‘What is His name?’ what will I say to them?”",
        "And God said to Moses, “I AM THAT I AM.” And He said, “Thus you will say to the children of Israel, ‘I AM has sent me to you.’”",
        "And God said moreover to Moses, “Thus you will say to the children of Israel, ‘The Lord God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob, has sent me to you.’ This is My name forever, and this is My memorial to all generations.”",
        "“Go, and gather the elders of Israel together, and say to them, ‘The Lord God of your fathers, the God of Abraham, of Isaac, and of Jacob, appeared to me, saying, I have surely visited you, and seen that which is done to you in Egypt.’”",
        "“And I have said, ‘I will bring you up out of the affliction of Egypt to the land of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, to a land flowing with milk and honey.’”",
        "“And they will listen to your voice. And you will come, you and the elders of Israel, to the king of Egypt, and you will say to him, ‘The Lord God of the Hebrews has met with us. And now let us go, we beg you, three days’ journey into the wilderness, that we may sacrifice to the Lord our God.’”",
