        "And the Lord said to Moses, “Go in to Pharaoh: for I have hardened his heart, and the heart of his servants, that I might show these My signs before him:”",
        "“And that you may tell in the ears of your son, and of your son’s son, what things I have wrought in Egypt, and My signs which I have done among them; that you may know how that I am the Lord.”",
