        "“Else, if you refuse to let My people go, behold, tomorrow will I bring the locusts into your coast:”",
        "“And they will cover the face of the earth, that one cannot be able to see the earth: and they will eat the residue of that which is escaped, which remains to you from the hail, and will eat every tree which grows for you out of the field:”",
        "“And they will fill your houses, and the houses of all your servants, and the houses of all the Egyptians; which neither your fathers, nor your fathers’ fathers have seen, since the day that they were upon the earth to this day.” And he turned himself, and went out from Pharaoh.",
        "And Pharaoh’s servants said to him, “How long will this man be a snare to us? Let the men go, that they may serve the Lord their God: do you not yet know that Egypt is destroyed?”",
