        "“You will not take the name of the Lord your God in vain; for the Lord will not hold him guiltless that takes His name in vain.”",
        "“Remember the sabbath day, to keep it holy.”",
        "“Six days will you labor, and do all your work:”",
        "“But the seventh day is the sabbath of the Lord your God: in it you will not do any work, you, nor your son, nor your daughter, your manservant, nor your maidservant, nor your cattle, nor your stranger that is within your gates:”",
        "“For in six days the Lord made heaven and earth, the sea, and all that in them is, and rested the seventh day: therefore the Lord blessed the sabbath day, and made it holy.”",
        "“Honor your father and your mother: that your days may be long upon the land which the Lord your God gives you.”",
