      "ch": "Exodus 30",
      "verses": [
        "And you shall make an altar to burn incense upon: of shittim wood shall you make it.",
        "A cubit shall be the length of it, and a cubit the breadth of it; foursquare shall it be: and two cubits shall be the height of it: the horns of it shall be of the same.",
        "And you shall overlay it with pure gold, the top of it, and the sides of it round about, and the horns of it; and you shall make to it a crown of gold round about.",
        "And two golden rings shall you make to it under the crown of it, by the two corners of it, upon the two sides of it shall you make it; and they shall be for places for the poles to carry it with.",
        "And you shall make the poles of shittim wood, and overlay them with gold.",
        "And you shall put it before the veil that is by the ark of the testimony, before the mercy seat that is over the testimony, where I will meet with you.",
        "And Aaron shall burn on it sweet incense every morning: when he dresses the lamps, he shall burn incense upon it.",
        "And when Aaron lights the lamps at evening, he shall burn incense upon it, a perpetual incense before the Lord throughout your generations.",
        "You shall offer no strange incense on it, nor burnt sacrifice, nor grain offering; neither shall you pour drink offering on it.",
        "And Aaron shall make an atonement upon the horns of it once in a year with the blood of the sin offering of atonements: once in the year shall he make atonement upon it throughout your generations: it is most holy to the Lord.",
        "And the Lord spoke to Moses, saying,",
        "“When you take the sum of the children of Israel after their number, then shall they give every man a ransom for his soul to the Lord, when you number them; that there be no plague among them, when you number them.”",
        "“This they shall give, every one that passes among them that are numbered, half a shekel after the shekel of the sanctuary: (a shekel is twenty gerahs:) a half shekel shall be the offering of the Lord.”",
        "“Every one that passes among them that are numbered, from twenty years old and above, shall give an offering to the Lord.”",
        "“The rich shall not give more, and the poor shall not give less than half a shekel, when they give an offering to the Lord, to make an atonement for your souls.”",
        "“And you shall take the atonement money of the children of Israel, and shall appoint it for the service of the tabernacle of the congregation; that it may be a memorial to the children of Israel before the Lord, to make an atonement for your souls.”",
        "And the Lord spoke to Moses, saying,",
        "“You shall also make a laver of brass, and its foot also of brass, to wash with: and you shall put it between the tabernacle of the congregation and the altar, and you shall put water in it.”",
        "“For Aaron and his sons shall wash their hands and their feet there:”",
        "“When they go into the tabernacle of the congregation, they shall wash with water, that they die not; or when they come near to the altar to minister, to burn offering made by fire to the Lord:”",
        "“So they shall wash their hands and their feet, that they die not: and it shall be a statute for ever to them, even to him and to his seed throughout their generations.”",
        "Moreover the Lord spoke to Moses, saying,",
        "“Take also to you principal spices, of pure myrrh five hundred shekels, and of sweet cinnamon half so much, even two hundred and fifty shekels, and of sweet calamus two hundred and fifty shekels,”",
        "“And of cassia five hundred shekels, after the shekel of the sanctuary, and of oil olive a hin:”",
        "“And you shall make it an oil of holy ointment, an ointment compound after the art of the apothecary: it shall be a holy anointing oil.”",
        "“And you shall anoint the tabernacle of the congregation with it, and the ark of the testimony,”",
        "“And the table and all its vessels, and the lampstand and its vessels, and the altar of incense,”",
        "“And the altar of burnt offering with all its vessels, and the laver and its foot.”",
        "“And you shall sanctify them, that they may be most holy: whatever touches them shall be holy.”",
        "“And you shall anoint Aaron and his sons, and consecrate them, that they may minister to Me in the priest's office.”",
        "“And you shall speak to the children of Israel, saying, ‘This shall be a holy anointing oil to Me throughout your generations.’”",
        "“‘Upon man's flesh shall it not be poured, neither shall you make any other like it, after the composition of it: it is holy, and it shall be holy to you.’”",
        "“‘Whoever compounds any like it, or whoever puts any of it upon a stranger, shall even be cut off from his people.’”",
        "And the Lord said to Moses, “Take to you sweet spices, stacte, and onycha, and galbanum; these sweet spices with pure frankincense: of each shall there be a like weight:”",
        "“And you shall make it a perfume, a confection after the art of the apothecary, tempered together, pure and holy:”",
        "“And you shall beat some of it very small, and put of it before the testimony in the tabernacle of the congregation, where I will meet with you: it shall be to you most holy.”",
        "“And as for the perfume which you shall make, you shall not make to yourselves according to the composition of it: it shall be to you holy for the Lord.”",
        "“Whoever shall make like to that, to smell it, shall even be cut off from his people.”"
      ],
