        "And the Lord spoke to Moses, saying,",
        "“See, I have called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah:”",
        "“And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship,”",
        "“To devise cunning works, to work in gold, and in silver, and in brass,”",
        "“And in cutting of stones, to set them, and in carving of timber, to work in all manner of workmanship.”",
        "“And I, behold, I have given with him Aholiab, the son of Ahisamach, of the tribe of Dan: and in the hearts of all that are wise hearted I have put wisdom, that they may make all that I have commanded you;”",
        "“The tabernacle of the congregation, and the ark of the testimony, and the mercy seat that is on it, and all the furniture of the tabernacle,”",
        "“And the table and its furniture, and the pure lampstand with all its furniture, and the altar of incense,”",
        "“And the altar of burnt offering with all its furniture, and the laver and its foot,”",
        "“And the cloths of service, and the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest's office,”",
        "“And the anointing oil, and sweet incense for the holy place: according to all that I have commanded you shall they do.”",
        "And the Lord spoke to Moses, saying,",
        "“Speak you also to the children of Israel, saying, ‘Verily My sabbaths you shall keep: for it is a sign between Me and you throughout your generations; that you may know that I am the Lord that sanctifies you.’”",
        "“You shall keep the sabbath therefore; for it is holy to you: every one that defiles it shall surely be put to death: for whoever does any work in it, that soul shall be cut off from among his people.”",
        "“Six days may work be done; but in the seventh is the sabbath of rest, holy to the Lord: whoever does any work in the sabbath day, he shall surely be put to death.”",
        "“Therefore the children of Israel shall keep the sabbath, to observe the sabbath throughout their generations, for a perpetual covenant.”",
        "“It is a sign between Me and the children of Israel for ever: for in six days the Lord made heaven and earth, and on the seventh day He rested, and was refreshed.”",
        "And He gave to Moses, when He had made an end of communing with him upon mount Sinai, two tables of testimony, tables of stone, written with the finger of God."
